<script setup lang="ts">
const props=defineProps<{graph:any;highlight?:string[]}>();const element=ref<HTMLElement|null>(null);let cy:any
function elements(){const nodes=(props.graph?.nodes||[]).map((n:any)=>({data:{id:n.node_id,label:n.name,type:n.node_type},classes:(props.highlight||[]).includes(n.node_id)?'highlight':''}));const assignments=(props.graph?.assignments||[]).map((e:any)=>({data:{id:e.assignment_id,source:e.from_id,target:e.to_id,label:'assigned'},classes:'assignment'}));const associations=(props.graph?.associations||[]).map((e:any)=>({data:{id:e.association_id,source:e.user_attribute_id,target:e.object_attribute_id,label:e.operations.join(', ')},classes:'association'}));return[...nodes,...assignments,...associations]}
onMounted(async()=>{const cytoscape=(await import('cytoscape')).default;cy=cytoscape({container:element.value,elements:elements(),style:[{selector:'node',style:{'background-color':'#1976d2','label':'data(label)','color':'#dbeafe','font-size':10,'text-valign':'bottom','text-margin-y':6}},{selector:'node[type="policy_class"]',style:{'background-color':'#7c4dff','shape':'diamond'}},{selector:'edge',style:{'curve-style':'bezier','target-arrow-shape':'triangle','line-color':'#607d8b','target-arrow-color':'#607d8b','width':2,'label':'data(label)','color':'#90a4ae','font-size':8}},{selector:'.association',style:{'line-color':'#26a69a','target-arrow-color':'#26a69a','line-style':'dashed'}},{selector:'.highlight',style:{'border-width':4,'border-color':'#ffca28'}}],layout:{name:'cose',animate:false}})});watch(()=>props.graph,()=>{if(cy){cy.elements().remove();cy.add(elements());cy.layout({name:'cose',animate:false}).run()}},{deep:true});onBeforeUnmount(()=>cy?.destroy())
</script>
<template><div ref="element" class="ngac-graph" aria-label="NGAC relationship graph"/></template>
<style scoped>.ngac-graph{height:520px;border:1px solid rgba(255,255,255,.12);border-radius:12px;background:#071522}</style>
